NFSE.NOTAS:
        {% for rps in nfse.lista_rps %}
        {% set dataemissao = rps.data_emissao.split('T')[0].split('-') %}

			{{ rps.numero }}
			{{ nfse.numero_lote }}
            {{ dataemissao[2] }}/{{ dataemissao[1] }}/{{ dataemissao[0] }}
			{{ rps.data_emissao.split('T')[1] }}
            {% if rps.servico.codigo_municipio == rps.tomador.codigo_municipio %}
			    D
            {% else %}
                F
            {% endif %}
			{% if rps.optante_simples|int == 1 %}
				4
			{% else %}
				1
			{% endif %}
            {% if rps.servico.iss_retido|int == 1 %}
			    S
            {% elif rps.servico.iss_retido|int == 2 %}
			    N
            {% endif %}
			{{ rps.servico.cnae_servico }}
			{{ rps.servico.aliquota|float * 100 }}
			{{ rps.servico.deducoes|default(0.00, true) }}
			{{ rps.servico.iss }}
            {% if rps.servico.iss|int == 1 %}
			{{ rps.servico.iss }}
            {% else %}
            0.00
            {% endif %}
			{{ rps.servico.informacao_complementar|default("", true) }}

                {% if rps.tomador.cpf_cnpj|length == 14  %}
				    J
                {% elif rps.tomador.cpf_cnpj|length == 11 %}
                    F
                {% endif %}
				{{ rps.tomador.cpf_cnpj }}
				{{ rps.tomador.razao_social }}
				{{ rps.tomador.codigo_municipio }}
				{{ rps.tomador.bairro }}
				{{ rps.tomador.cep }}
				END:
				{{ rps.tomador.endereco }}
				{{ rps.tomador.complemento }}
				{{ rps.tomador.numero }}
				S


                {% if rps.servico.iss_retido|int == 1 %}
				    T
                {% elif rps.servico.iss_retido|int == 2 %}
                    P
                {% endif %}
				{{ rps.servico.pis|default("0.00", true) }}
				{{ rps.servico.cofins|default("0.00", true) }}
				{{ rps.servico.inss|default("0.00", true) }}
				{{ rps.servico.ir|default("0.00", true) }}
				{{ rps.servico.csll|default("0.00", true) }}
				{{ rps.servico.retencoes|default("0.00", true) }}



					{{ rps.servico.discriminacao }}
					{{ rps.servico.valor_servico }}
					1



        {% endfor %}
